import SpecialFunctions: loggamma
import JSON

# Evaluate the entropy in extended precision, as the double-precision series used by `Distributions.entropy( Poisson( lambda ) )` is only accurate to tens of ULPs (and switches to an asymptotic expansion for `lambda >= 50`):
setprecision( BigFloat, 256 );

"""
	poisson_entropy( lambda )

Compute the entropy of a Poisson distribution as `-sum( p_k * ln(p_k) )` in extended precision.

# Arguments

* `lambda`: mean parameter

# Examples

``` julia
julia> poisson_entropy( 9.0 )
2.507673896080289
```
"""
function poisson_entropy( lambda )
	l = BigFloat( lambda );
	ll = log( l );

	# Terms more than 40 standard deviations from the mean are smaller than `exp(-800)`:
	lo = max( 0, floor( Int, lambda - 40.0*sqrt( lambda ) ) );
	hi = ceil( Int, lambda + 40.0*sqrt( lambda ) + 40.0 );
	h = zero( BigFloat );
	for k in lo:hi
		lp = k*ll - l - loggamma( BigFloat( k+1 ) );
		h -= exp( lp ) * lp;
	end
	return Float64( h );
end

"""
	gen( lambda, name )

Generate fixture data and write to file.

# Arguments

* `lambda`: mean parameter
* `name::AbstractString`: output filename

# Examples

``` julia
julia> lambda = rand( 1000 );
julia> gen( lambda, \"data.json\" );
```
"""
function gen( lambda, name )
	z = Array{Float64}( undef, length(lambda) );
	for i in eachindex(lambda)
		z[ i ] = poisson_entropy( lambda[ i ] );
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("lambda", lambda),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Generate fixtures:
lambda = rand( 500 ) .* 20.0;
gen( lambda, "data.json" );

lambda = ( rand( 200 ) .* 4980.0 ) .+ 20.0;
gen( lambda, "medium.json" );

lambda = exp10.( ( rand( 100 ) .* 2.0 ) .+ 3.7 );
gen( lambda, "large.json" );

